import { readFile } from 'node:fs/promises';
import { describe, it, expect } from 'vitest';

// The production page is generated by builder/prod/prod.js, the development page is builder/dev/index.html.
const pages = [
  ['index.html', await readFile('index.html', 'utf8')],
  ['builder/dev/index.html', await readFile('builder/dev/index.html', 'utf8')],
  ['builder/prod/prod.js', await readFile('builder/prod/prod.js', 'utf8')],
];

describe('platform page', () => {
  it.each(pages)('%s has no inline script, as the Content-Security-Policy blocks them', (_, page) => {
    expect(page).not.toMatch(/<script(?![^>]*\ssrc=)[^>]*>/i);
    expect(page).toContain('<meta name="base-path" content="%BASE_PATH%">');
  });
});
